excels.excel:

EXPORT WITH SHEET="生产排产计划表", HEADER=true,
    MAPPING={"a":"产线","b":"产品名称","c":"计划产量","d":"日产能","e":"需求天数","f":"计划投入工时","g":"排产状态"},
    FORMAT={"c":"#,##0","d":"#,##0","e":"0.0","f":"#,##0"},
    FORMULAS={
        E2:'C2/D2',F2:'E2*8',E3:'C3/D3',F3:'E3*8',E4:'C4/D4',F4:'E4*8',
        E5:'C5/D5',F5:'E5*8',E6:'C6/D6',F6:'E6*8',
        C7:'SUM(C2:C6)',E7:'SUM(E2:E6)',F7:'SUM(F2:F6)'
    },
    STYLE={
        ROW 7:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        E4:{color:red,bold:true}
    }
